package com.example.order;

import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.http.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Testcontainers
class TmpProbeTest {
    @Container @ServiceConnection static PostgreSQLContainer<?> pg = new PostgreSQLContainer<>("postgres:16-alpine");
    @Autowired TestRestTemplate rest;

    void p(String label, HttpMethod m, String url, String body) {
        HttpHeaders h = new HttpHeaders(); h.setContentType(MediaType.APPLICATION_JSON); h.setAccept(List.of(MediaType.APPLICATION_JSON));
        ResponseEntity<String> r = rest.exchange(url, m, new HttpEntity<>(body, h), String.class);
        System.out.println("PROBE " + label + " -> " + r.getStatusCode().value() + " " + r.getHeaders().getContentType() + " " + r.getBody());
    }
    @Test void probe() {
        p("float stock", HttpMethod.POST, "/api/products", "{\"name\":\"a\",\"price\":1,\"stock\":1.5}");
        p("str price", HttpMethod.POST, "/api/products", "{\"name\":\"a\",\"price\":\"1\",\"stock\":1}");
        p("blank", HttpMethod.POST, "/api/products", "{\"name\":\"  \",\"price\":0}");
        p("bad json", HttpMethod.POST, "/api/products", "{bad");
        p("empty body", HttpMethod.POST, "/api/products", null);
        p("prod ok", HttpMethod.POST, "/api/products", "{\"name\":\"a\",\"price\":100,\"stock\":2}");
        p("get abc", HttpMethod.GET, "/api/products/abc", null);
        p("get 404", HttpMethod.GET, "/api/products/999", null);
        p("dup", HttpMethod.POST, "/api/orders", "{\"items\":[{\"productId\":1,\"quantity\":1},{\"productId\":1,\"quantity\":1}]}");
