1	package com.example.order.order;
2	
3	import com.example.order.common.web.PageResponse;
4	import com.example.order.order.dto.CreateOrderRequest;
5	import com.example.order.order.dto.OrderItemRequest;
6	import com.example.order.order.dto.OrderResponse;
7	import com.example.order.product.InsufficientStockException;
8	import com.example.order.product.Product;
9	import com.example.order.product.ProductNotFoundException;
10	import com.example.order.product.ProductRepository;
11	import java.util.Comparator;
12	import java.util.HashMap;
13	import java.util.List;
14	import java.util.Map;
15	import org.springframework.data.domain.Page;
16	import org.springframework.data.domain.PageRequest;
17	import org.springframework.data.domain.Sort;
18	import org.springframework.stereotype.Service;
19	import org.springframework.transaction.annotation.Transactional;
20	
21	@Service
22	public class OrderService {
23	
24	    private static final Sort LIST_SORT = Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id"));
25	
26	    private final OrderRepository orderRepository;
27	    private final ProductRepository productRepository;
28	
29	    public OrderService(OrderRepository orderRepository, ProductRepository productRepository) {
30	        this.orderRepository = orderRepository;
31	        this.productRepository = productRepository;
32	    }
33	
34	    @Transactional
35	    public OrderResponse create(CreateOrderRequest request) {
36	        List<OrderItemRequest> requested = request.items();
37	
38	        // 1. 존재 확인 (읽기만). 하나라도 없으면 404 — 차감(409 판정)보다 먼저.
39	        List<Long> ids = requested.stream().map(OrderItemRequest::productId).toList();
40	        Map<Long, Product> products = new HashMap<>();
41	        for (Product p : productRepository.findAllById(ids)) {
42	            products.put(p.getId(), p);
43	        }
44	        List<Long> missing = ids.stream().filter(id -> !products.containsKey(id)).sorted().toList();
45	        if (!missing.isEmpty()) {
46	            throw new ProductNotFoundException(missing);
47	        }
48	
49	        // 2. productId 오름차순으로 조건부 차감 (데드락 방지). 영향 행 0이면 409 + 롤백.
50	        List<OrderItemRequest> sorted = requested.stream()
51	                .sorted(Comparator.comparing(OrderItemRequest::productId))
52	                .toList();
53	        for (OrderItemRequest item : sorted) {
54	            if (productRepository.decreaseStock(item.productId(), item.quantity()) == 0) {
55	                throw new InsufficientStockException(item.productId(), item.quantity());
56	            }
57	        }
58	
59	        // 3. 합계 계산 (오버플로 시 ArithmeticException -> 400) + 4. 저장 (요청 순서 유지)
60	        long total = 0;
61	        for (OrderItemRequest item : requested) {
62	            long unitPrice = products.get(item.productId()).getPrice();
63	            total = Math.addExact(total, Math.multiplyExact(unitPrice, (long) item.quantity()));
64	        }
65	        Order order = new Order(total);
66	        for (OrderItemRequest item : requested) {
67	            order.addItem(new OrderItem(item.productId(), item.quantity(),
68	                    products.get(item.productId()).getPrice()));
69	        }
70	        Order saved = orderRepository.save(order);
71	        return OrderResponse.from(saved);
72	    }
73	
74	    @Transactional(readOnly = true)
75	    public OrderResponse get(Long id) {
76	        return orderRepository.findWithItemsById(id)
77	                .map(OrderResponse::from)
78	                .orElseThrow(() -> new OrderNotFoundException(id));
79	    }
80	
81	    @Transactional
82	    public OrderResponse cancel(Long id) {
83	        if (!orderRepository.existsById(id)) {
84	            throw new OrderNotFoundException(id);
85	        }
86	        if (orderRepository.cancelIfOrdered(id) == 0) {
87	            throw new OrderAlreadyCancelledException(id);
88	        }
89	        Order order = orderRepository.findWithItemsById(id)
90	                .orElseThrow(() -> new OrderNotFoundException(id));
91	        List<OrderItem> items = order.getItems().stream()
92	                .sorted(Comparator.comparing(OrderItem::getProductId))
93	                .toList();
94	        for (OrderItem item : items) {
95	            productRepository.increaseStock(item.getProductId(), item.getQuantity());
96	        }
97	        return OrderResponse.from(order);
98	    }
99	
100	    @Transactional(readOnly = true)
101	    public PageResponse<OrderResponse> list(int page, int size) {
102	        Page<Order> result = orderRepository.findAll(PageRequest.of(page, size, LIST_SORT));
103	        List<OrderResponse> content = result.getContent().stream().map(OrderResponse::from).toList();
104	        return new PageResponse<>(content, page, size, result.getTotalElements());
105	    }
106	}
