10	import java.util.ArrayList;
11	import java.util.List;
12	import java.util.Map;
13	import org.slf4j.Logger;
14	import org.slf4j.LoggerFactory;
15	import org.springframework.beans.TypeMismatchException;
16	import org.springframework.context.MessageSourceResolvable;
17	import org.springframework.http.HttpHeaders;
18	import org.springframework.http.HttpStatus;
19	import org.springframework.http.HttpStatusCode;
20	import org.springframework.http.MediaType;
21	import org.springframework.http.ProblemDetail;
22	import org.springframework.http.ResponseEntity;
23	import org.springframework.http.converter.HttpMessageNotReadableException;
24	import org.springframework.lang.Nullable;
25	import org.springframework.validation.FieldError;
26	import org.springframework.validation.ObjectError;
27	import org.springframework.web.bind.MethodArgumentNotValidException;
28	import org.springframework.web.bind.annotation.ExceptionHandler;
29	import org.springframework.web.bind.annotation.RestControllerAdvice;
30	import org.springframework.web.context.request.WebRequest;
31	import org.springframework.web.method.annotation.HandlerMethodValidationException;
32	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
33	
34	/**
35	 * 모든 에러를 RFC 9457 ProblemDetail(application/problem+json)로 변환한다.
36	 */
37	@RestControllerAdvice
38	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
39	
40	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
41	
42	    // ---- 프레임워크 표준 예외 오버라이드 ----
43	
44	    @Override
45	    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
46	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
47	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.MALFORMED_REQUEST, "Malformed Request",
48	                "요청 본문을 해석할 수 없습니다. JSON 형식과 필드 타입을 확인하세요.");
49	        return handleExceptionInternal(ex, pd, headers, HttpStatus.BAD_REQUEST, request);
50	    }
51	
52	    @Override
53	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
54	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
55	        List<Map<String, String>> errors = new ArrayList<>();
56	        for (ObjectError error : ex.getBindingResult().getAllErrors()) {
57	            String field = error instanceof FieldError fe ? fe.getField() : error.getObjectName();
58	            errors.add(Map.of("field", field, "message", String.valueOf(error.getDefaultMessage())));
59	        }
60	        ProblemDetail pd = validationProblem(errors);
61	        return handleExceptionInternal(ex, pd, headers, HttpStatus.BAD_REQUEST, request);
62	    }
63	
64	    @Override
65	    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
66	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
67	        List<Map<String, String>> errors = new ArrayList<>();
68	        ex.getParameterValidationResults().forEach(result -> {
69	            String field = result.getMethodParameter().getParameterName();
70	            for (MessageSourceResolvable error : result.getResolvableErrors()) {
71	                errors.add(Map.of("field", field == null ? "unknown" : field,
72	                        "message", String.valueOf(error.getDefaultMessage())));
73	            }
74	        });
75	        ProblemDetail pd = validationProblem(errors);
76	        return handleExceptionInternal(ex, pd, headers, HttpStatus.BAD_REQUEST, request);
77	    }
78	
79	    @Override
80	    protected ResponseEntity<Object> handleTypeMismatch(TypeMismatchException ex, HttpHeaders headers,
81	            HttpStatusCode status, WebRequest request) {
82	        String name = ex.getPropertyName() != null ? ex.getPropertyName() : "parameter";
83	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.INVALID_PARAMETER, "Invalid Parameter",
84	                "요청 파라미터 '" + name + "'의 형식이 올바르지 않습니다.");
85	        return handleExceptionInternal(ex, pd, headers, HttpStatus.BAD_REQUEST, request);
86	    }
87	
88	    /** 모든 ProblemDetail 응답의 Content-Type을 application/problem+json으로 고정한다. */
89	    @Override
90	    protected ResponseEntity<Object> createResponseEntity(@Nullable Object body, HttpHeaders headers,
91	            HttpStatusCode statusCode, WebRequest request) {
92	        HttpHeaders forced = new HttpHeaders();
93	        forced.putAll(headers);
94	        forced.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
95	        return super.createResponseEntity(body, forced, statusCode, request);
96	    }
97	
98	    // ---- 도메인 예외 ----
99	
100	    @ExceptionHandler(ProductNotFoundException.class)
101	    public ResponseEntity<ProblemDetail> handleProductNotFound(ProductNotFoundException ex,
102	            HttpServletRequest request) {
103	        return respond(problem(HttpStatus.NOT_FOUND, ProblemTypes.PRODUCT_NOT_FOUND, "Product Not Found",
104	                ex.getMessage(), request));
105	    }
106	
107	    @ExceptionHandler(OrderNotFoundException.class)
108	    public ResponseEntity<ProblemDetail> handleOrderNotFound(OrderNotFoundException ex,
109	            HttpServletRequest request) {
110	        return respond(problem(HttpStatus.NOT_FOUND, ProblemTypes.ORDER_NOT_FOUND, "Order Not Found",
111	                ex.getMessage(), request));
112	    }
113	
114	    @ExceptionHandler(InsufficientStockException.class)
115	    public ResponseEntity<ProblemDetail> handleInsufficientStock(InsufficientStockException ex,
116	            HttpServletRequest request) {
117	        return respond(problem(HttpStatus.CONFLICT, ProblemTypes.INSUFFICIENT_STOCK, "Insufficient Stock",
118	                ex.getMessage(), request));
119	    }
120	
121	    @ExceptionHandler(OrderAlreadyCancelledException.class)
122	    public ResponseEntity<ProblemDetail> handleAlreadyCancelled(OrderAlreadyCancelledException ex,
123	            HttpServletRequest request) {
124	        return respond(problem(HttpStatus.CONFLICT, ProblemTypes.ORDER_ALREADY_CANCELLED,
125	                "Order Already Cancelled", ex.getMessage(), request));
126	    }
127	
128	    // ---- 안전망 ----
129	
130	    @ExceptionHandler(ConstraintViolationException.class)
131	    public ResponseEntity<ProblemDetail> handleConstraintViolation(ConstraintViolationException ex,
132	            HttpServletRequest request) {
133	        List<Map<String, String>> errors = ex.getConstraintViolations().stream()
134	                .map(v -> Map.of("field", v.getPropertyPath().toString(), "message", v.getMessage()))
135	                .toList();
136	        ProblemDetail pd = validationProblem(errors);
137	        setInstance(pd, request);
138	        return respond(pd);
139	    }
140	
141	    @ExceptionHandler(ArithmeticException.class)
142	    public ResponseEntity<ProblemDetail> handleArithmetic(ArithmeticException ex, HttpServletRequest request) {
143	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.VALIDATION_ERROR, "Validation Failed",
144	                "금액 합계가 표현 범위를 초과합니다", request);
145	        pd.setProperty("errors", List.of());
146	        return respond(pd);
147	    }
148	
149	    @ExceptionHandler(Exception.class)
150	    public ResponseEntity<ProblemDetail> handleUnexpected(Exception ex, HttpServletRequest request) {
151	        log.error("Unhandled exception: {} {}", request.getMethod(), request.getRequestURI(), ex);
152	        return respond(problem(HttpStatus.INTERNAL_SERVER_ERROR, ProblemTypes.INTERNAL_ERROR,
153	                "Internal Server Error", "예상치 못한 오류가 발생했습니다.", request));
154	    }
155	
156	    // ---- 헬퍼 ----
157	
158	    private ProblemDetail validationProblem(List<Map<String, String>> errors) {
159	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.VALIDATION_ERROR, "Validation Failed",
160	                "요청 값이 유효하지 않습니다.");
161	        pd.setProperty("errors", errors);
162	        return pd;
163	    }
164	
165	    private ProblemDetail problem(HttpStatus status, URI type, String title, String detail) {
166	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
167	        pd.setType(type);
168	        pd.setTitle(title);
169	        return pd;
170	    }
171	
172	    private ProblemDetail problem(HttpStatus status, URI type, String title, String detail,
173	            HttpServletRequest request) {
174	        ProblemDetail pd = problem(status, type, title, detail);
175	        setInstance(pd, request);
176	        return pd;
177	    }
178	
179	    private void setInstance(ProblemDetail pd, HttpServletRequest request) {
180	        try {
181	            pd.setInstance(URI.create(request.getRequestURI()));
182	        } catch (IllegalArgumentException ignored) {
183	            // instance는 선택 필드이므로 생략한다.
184	        }
185	    }
186	
187	    private ResponseEntity<ProblemDetail> respond(ProblemDetail pd) {
188	        return ResponseEntity.status(pd.getStatus())
189	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
190	                .body(pd);
191	    }
192	}
